sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

 var course = g_form.getValue('training');
    var date = g_form.getValue('schedule_for').split("/");
    date = date[2] + "-" + date[1] + "-" + date[0];

    if (!course || !date) {
        return;
    }

    var ga = new GlideAjax('x_1805892_compan_0.ValidateTrainingSchedule');
    ga.addParam('sysparm_name', 'validateDate');
    ga.addParam('sysparm_course', course.toString());
    ga.addParam('sysparm_date', date.toString());

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            g_form.setValue('training', '');
            g_form.setValue('schedule_for', '');
            g_form.showErrorBox('schedule_for', 'There is already a schedule for that date and course', true);
        }
    });

}
